fn despawn_camera_entities(world: &mut engine::ecs::World) {
    let mut camera_entities: Vec<engine::ecs::Entity> = {
        let q = engine::Query::<&Camera3D>::new(world);
        q.iter().map(|(entity, _)| entity).collect()
    };
    {
        let q = engine::Query::<&engine::Camera2d>::new(world);
        for (entity, _) in q.iter() {
            if !camera_entities.contains(&entity) {
                camera_entities.push(entity);
            }
        }
    }
    for entity in camera_entities {
        let _ = world.despawn(entity);
    }
}

fn update_editor_camera(
    world: &mut engine::ecs::World,
    cam_transform: Transform,
    dimension: SceneViewDimension,
    aspect: f32,
    orthographic_height: f32,
) {
    if let Ok(entity) = world.spawn() {
        let matrix = cam_transform.to_matrix();
        let _ = world.add_component(entity, cam_transform);
        let _ = world.add_component(entity, GlobalTransform(matrix));
        match dimension {
            SceneViewDimension::ThreeD => {
                let _ = world.add_component(entity, Camera3D::new(60.0, aspect, 0.1, 1000.0));
            }
            SceneViewDimension::TwoD => {
                let _ = world.add_component(
                    entity,
                    engine::Camera2d {
                        orthographic_height,
                        ..engine::Camera2d::default()
                    },
                );
            }
        }
    }
}
